const n = items.length;
if (n === 0) return 0;
const W = maximumWeight;
const dp = Array.from({ length: n + 1 }, () => Array(W + 1).fill(0));
for (let i = 1; i <= n; i++) {
  const item = items[i - 1];
  for (let w = 0; w <= W; w++) {
    dp[i][w] = dp[i - 1][w];
    if (item.weight <= w) {
